import { z } from 'zod';
import { VALID_PATH_REGEX } from '../../../dev-center/components/validations/common.js';
import { createDashboardRouteValidation } from '../../../dev-center/components/validations/dashboard-page.js';
import type { ExtensionDef } from '../generate-schema/types.js';
import { defineField } from '../generate-schema/definitions.js';
import { generateDashboardPage } from './generate.js';

const schema = z.object({
  extensionType: z.literal('DASHBOARD_PAGE'),
  title: z
    .string()
    .describe(defineField({ title: 'Page title', default: 'My Custom Page' })),
  route: z
    .string()
    .regex(VALID_PATH_REGEX)
    .describe(
      defineField({
        title: 'Page route',
        description:
          'Lowercase alphanumeric, hyphens, and slashes. Used as the page URL path and the extension folder name.',
        default: 'my-page',
      })
    ),
});

export const dashboardPage: ExtensionDef<typeof schema> = {
  title: 'Dashboard Page',
  description: 'Create a custom dashboard page',
  group: 'Dashboard',
  documentation:
    'https://dev.wix.com/docs/studio-two/code-your-site/extensions/dashboard/dashboard-pages/add-a-dashboard-page-extension',
  zodSchema: schema,
  validate: async (projectFolder, data) => {
    const result = createDashboardRouteValidation(projectFolder)(data.route);
    return result.valid ? null : result.reason;
  },
  generate: ({ projectFolder, data }) =>
    generateDashboardPage(projectFolder, data.route, data.title),
};
