import { z } from 'zod';
import { getFunctionLibraryExtensionsDir } from '@wix/cli-astro-definitions';
import {
  folderExistsMessage,
  pathAvailableValidation,
  VALID_PATH_REGEX,
} from '../../../dev-center/components/validations/common.js';
import type { ExtensionDef } from '../generate-schema/types.js';
import { defineField } from '../generate-schema/definitions.js';
import { enrichWithDerivedFolder } from '../utils/derive-folder.js';
import type { WithDerivedFolder } from '../utils/derive-folder.js';
import { generateFunctionLibrary } from './generate.js';

const schema = z.object({
  extensionType: z.literal('FUNCTION_LIBRARY'),
  name: z.string().describe(defineField({ title: 'Extension name' })),
  folder: z
    .string()
    .regex(VALID_PATH_REGEX)
    .optional()
    .describe(
      defineField({
        title: 'Extension folder',
        description:
          'Lowercase alphanumeric and hyphens only. Derived from the extension name when omitted.',
      })
    ),
});

export const functionLibrary: ExtensionDef<
  typeof schema,
  WithDerivedFolder<typeof schema>
> = {
  title: 'Function Library',
  description: 'Write reusable utility functions',
  group: 'Site',
  zodSchema: schema,
  enrich: (data) => enrichWithDerivedFolder(data, { sourceField: 'name' }),
  validate: async (projectFolder, data) => {
    const isAvailable = pathAvailableValidation(
      getFunctionLibraryExtensionsDir(projectFolder)
    )(data.folder);
    return isAvailable
      ? null
      : folderExistsMessage('function library', data.folder, 'name');
  },
  generate: ({ projectFolder, model, data }) =>
    generateFunctionLibrary(
      projectFolder,
      data.folder,
      data.name,
      model.config.projectType === 'App'
        ? model.config.codeIdentifier
        : undefined
    ),
};
